{
  "decision": "APPLY",
  "workflow_yaml": "name: Arch Linux

on: [push, pull_request]

env:
  QTIFWVER: 4.8.1
  APPIMAGEVER: continuous
  DOCKERIMG: archlinux:latest
  ARCH_ROOT_URL: https://mirror.rackspace.com/archlinux

jobs:
  build:
    runs-on: ubuntu-latest
    strategy:
      max-parallel: 10
      fail-fast: true
      matrix:
       include:
         - compiler: gcc
         - compiler: clang
    steps:
    - uses: actions/checkout@v6
      with:
        submodules: true
        token: ${{ secrets.UPLOAD_TOKEN }}
    - name: Release build
      uses: addnab/docker-run-action@v3
      if: ${{ startsWith(github.ref, 'refs/tags/') }}
      with:
        username: ${{ secrets.DOCKER_USERNAME }}
        password: ${{ secrets.DOCKER_PASSWORD }}
        registry: gcr.io
        image: ${{ env.DOCKERIMG }}
        options: >-
          -v ${{ github.workspace }}:/sources
          -e GITHUB_REF=${{ github.ref }}
          -e GITHUB_SERVER_URL=${{ github.server_url }}
          -e GITHUB_REPOSITORY=${{ github.repository }}
          -e GITHUB_RUN_ID=${{ github.run_id }}
          -e GIT_COMMIT_HASH=${{ github.sha }}
          -e GIT_BRANCH_NAME=${{ github.ref_name }}
          -e APPIMAGEVER=${{ env.APPIMAGEVER }}
          -e COMPILER=${{ matrix.compiler }}
          -e DOCKERIMG=${{ env.DOCKERIMG }}
          -e ARCH_ROOT_URL=${{ env.ARCH_ROOT_URL }}
          -e QTIFWVER=${{ env.QTIFWVER }}
        run: |
          cd /sources
          echo
          echo Install dependencies
          echo
          chmod +x ports/ci/linux-arch/install_deps.sh
          ./ports/ci/linux-arch/install_deps.sh
          echo
          echo Release Build
          echo
          chmod +x ports/ci/linux-arch/build.sh
          ./ports/ci/linux-arch/build.sh
          echo
          echo Release Deploy
          echo
          chmod +x ports/ci/linux-arch/deploy.sh
          ./ports/ci/linux-arch/deploy.sh
    - name: Daily build
      uses: addnab/docker-run-action@v3
      if: ${{ !startsWith(github.ref, 'refs/tags/') }}
      with:
        username: ${{ secrets.DOCKER_USERNAME }}
        password: ${{ secrets.DOCKER_PASSWORD }}
        registry: gcr.io
        image: ${{ env.DOCKERIMG }}
        options: >-
          -v ${{ github.workspace }}:/sources
          -e GITHUB_REF=${{ github.ref }}
          -e GITHUB_SERVER_URL=${{ github.server_url }}
          -e GITHUB_REPOSITORY=${{ github.repository }}
          -e GITHUB_RUN_ID=${{ github.run_id }}
          -e GIT_COMMIT_HASH=${{ github.sha }}
          -e GIT_BRANCH_NAME=${{ github.ref_name }}
          -e APPIMAGEVER=${{ env.APPIMAGEVER }}
          -e COMPILER=${{ matrix.compiler }}
          -e DOCKERIMG=${{ env.DOCKERIMG }}
          -e ARCH_ROOT_URL=${{ env.ARCH_ROOT_URL }}
          -e QTIFWVER=${{ env.QTIFWVER }}
          -e DAILY_BUILD=1
        run: |
          cd /sources
          echo
          echo Install dependencies
          echo
          chmod +x ports/ci/linux-arch/install_deps.sh
          ./ports/ci/linux-arch/install_deps.sh
          echo
          echo Daily Build
          echo
          chmod +x ports/ci/linux-arch/build.sh
          ./ports/ci/linux-arch/build.sh
          echo
          echo Daily Deploy
          echo
          chmod +x ports/ci/linux-arch/deploy.sh
          ./ports/ci/linux-arch/deploy.sh
",
  "rationale": "The workflow uses a matrix strategy with two compiler configurations (gcc and clang) and currently has `fail-fast: false`. Evidence from P-LIT-FAIL-FAST experiments (experiment:batch-scenario-three-run-4bb0552aeb09c242 and experiment:batch-scenario-three-run-b6e04fef7ef24997) demonstrates that changing `fail-fast: false` to `fail-fast: true` in matrix strategies is a supported optimization that can save CI resources by canceling remaining matrix jobs when one fails. This is a minimal, low-risk change that preserves all build and test coverage while potentially reducing wasted compute on failure scenarios. The change aligns with the pattern's preconditions and does not violate contraindications since the matrix outcomes are not strictly required to all complete (a failure in one compiler configuration typically indicates a code issue that would affect others).",
  "evidence_ids": ["experiment:batch-scenario-three-run-4bb0552aeb09c242", "experiment:batch-scenario-three-run-b6e04fef7ef24997"]
}
